type CartItem = { productId: string; quantity: number }
type StoreContextValue = {
  cart: CartItem[]
  wishlist: string[]
  library: string[]
  theme: 'light' | 'dark'
  addToCart: (product: Product) => void
  removeFromCart: (id: string) => void
  updateQuantity: (id: string, quantity: number) => void
  toggleWishlist: (id: string) => void
  purchase: (ids: string[]) => void
  toggleTheme: () => void
  cartCount: number
}

const StoreContext = createContext<StoreContextValue | null>(null)
const readStorage = <T,>(key: string, fallback: T): T => {
  try { const value = localStorage.getItem(key); return value ? JSON.parse(value) : fallback } catch { return fallback }
}

function StoreProvider({ children }: { children: ReactNode }) {
  const [cart, setCart] = useState<CartItem[]>(() => readStorage('ds-cart', []))
  const [wishlist, setWishlist] = useState<string[]>(() => readStorage('ds-wishlist', ['sw-02', 'bk-04']))
  const [library, setLibrary] = useState<string[]>(() => readStorage('ds-library', ['bk-01', 'co-08']))
  const [theme, setTheme] = useState<'light' | 'dark'>(() => readStorage('ds-theme', 'light'))
  useEffect(() => { localStorage.setItem('ds-cart', JSON.stringify(cart)) }, [cart])
  useEffect(() => { localStorage.setItem('ds-wishlist', JSON.stringify(wishlist)) }, [wishlist])
  useEffect(() => { localStorage.setItem('ds-library', JSON.stringify(library)) }, [library])
  useEffect(() => { localStorage.setItem('ds-theme', JSON.stringify(theme)); document.documentElement.classList.toggle('dark', theme === 'dark') }, [theme])
  const addToCart = (product: Product) => {
    if (product.isFree) { toast.success('Free download ready', { description: `${product.title} was added to your library.` }); setLibrary((current) => current.includes(product.id) ? current : [...current, product.id]); return }
    setCart((current) => current.some((item) => item.productId === product.id) ? current.map((item) => item.productId === product.id ? { ...item, quantity: item.quantity + 1 } : item) : [...current, { productId: product.id, quantity: 1 }])
    toast.success('Added to your bag', { description: product.title })
  }
  const removeFromCart = (id: string) => setCart((current) => current.filter((item) => item.productId !== id))
  const updateQuantity = (id: string, quantity: number) => setCart((current) => quantity < 1 ? current.filter((item) => item.productId !== id) : current.map((item) => item.productId === id ? { ...item, quantity } : item))
  const toggleWishlist = (id: string) => setWishlist((current) => current.includes(id) ? (toast('Removed from wishlist'), current.filter((item) => item !== id)) : (toast.success('Saved to wishlist'), [...current, id]))
  const purchase = (ids: string[]) => { setLibrary((current) => Array.from(new Set([...current, ...ids]))); setCart([]) }
  return <StoreContext.Provider value={{ cart, wishlist, library, theme, addToCart, removeFromCart, updateQuantity, toggleWishlist, purchase, toggleTheme: () => setTheme((t) => t === 'light' ? 'dark' : 'light'), cartCount: cart.reduce((sum, item) => sum + item.quantity, 0) }}>{children}</StoreContext.Provider>
}
function useStore() { const value = useContext(StoreContext); if (!value) throw new Error('useStore must be used inside StoreProvider'); return value }

