function Header() {
  const { theme, toggleTheme } = useStore()
  const cartCount = useCartStore((s) => s.items.reduce((sum, i) => sum + i.qty, 0))
  const wishlistCount = useWishlistStore((s) => s.items.length)
  const openCart = useCartStore((s) => s.openCart)
  const reduced = useReducedMotion()
  const [bump, setBump] = useState(false)
  const prevCount = useRef(cartCount)
  useEffect(() => {
    if (cartCount !== prevCount.current && cartCount > 0) {
      if (reduced) { prevCount.current = cartCount; return; }
      setBump(true)
      const t = setTimeout(() => setBump(false), 250)
      prevCount.current = cartCount
      return () => clearTimeout(t)
    }
    prevCount.current = cartCount
  }, [cartCount, reduced])
  const [location] = useLocation()
  const [menuOpen, setMenuOpen] = useState(false)
  const [categoriesOpen, setCategoriesOpen] = useState(false)
  const [mobileCategoriesOpen, setMobileCategoriesOpen] = useState(false)
  const [search, setSearch] = useState('')
  const categoriesRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    setCategoriesOpen(false)
    setMobileCategoriesOpen(false)
    setMenuOpen(false)
  }, [location])

  useEffect(() => {
    const handleOutsideClick = (event: MouseEvent) => {
      if (categoriesRef.current && !categoriesRef.current.contains(event.target as Node)) setCategoriesOpen(false)
    }
    document.addEventListener('mousedown', handleOutsideClick)
    return () => document.removeEventListener('mousedown', handleOutsideClick)
  }, [])

  const submitSearch = () => { window.location.href = `/shop?search=${encodeURIComponent(search)}` }
  const handleCategoryKeyDown = (event: React.KeyboardEvent<HTMLButtonElement>) => {
    if (event.key === 'Enter' || event.key === ' ' || event.key === 'ArrowDown') { event.preventDefault(); setCategoriesOpen(true) }
    if (event.key === 'Escape') { event.preventDefault(); setCategoriesOpen(false) }
  }

  return <>
    <header className="sticky top-0 z-40 border-b border-[#e7e6e1]/80 bg-[#f7f6f2]/90 backdrop-blur-xl">
      <div className="ds-container flex h-[72px] items-center justify-between gap-5">
        <Logo />
        <nav className="hidden items-center gap-6 lg:flex">
          <Link href="/shop" className={`text-[13px] font-semibold transition-colors hover:text-[#635BFF] ${location === '/shop' ? 'text-[#635BFF]' : 'text-[#6f7184]'}`}>Shop</Link>
          <div ref={categoriesRef} className="relative">
            <button aria-haspopup="menu" aria-expanded={categoriesOpen} onClick={() => setCategoriesOpen((open) => !open)} onKeyDown={handleCategoryKeyDown} className={`flex items-center gap-1.5 text-[13px] font-semibold transition-colors hover:text-[#635BFF] ${categoriesOpen ? 'text-[#635BFF]' : 'text-[#6f7184]'}`}>
              Categories <ChevronDown size={14} className={`transition-transform duration-200 ${categoriesOpen ? 'rotate-180' : ''}`} />
            </button>
            <div className={`absolute left-1/2 top-[calc(100%+18px)] w-[350px] -translate-x-1/2 rounded-2xl border border-[#e7e6e1] bg-white p-2 shadow-[0_18px_50px_rgba(40,39,77,.14)] transition-all duration-200 ${categoriesOpen ? 'pointer-events-auto translate-y-0 opacity-100' : 'pointer-events-none -translate-y-2 opacity-0'}`} role="menu" aria-label="Categories">
              <div className="mb-1 px-3 py-2 text-[10px] font-bold uppercase tracking-[.15em] text-[#9b9baa]">Browse categories</div>
              <div className="grid grid-cols-2 gap-1">
                {navbarCategories.map((category) => <Link key={category.slug} href={`/shop/${category.slug}`} onClick={() => setCategoriesOpen(false)} className="group flex gap-2.5 rounded-xl p-3 transition hover:bg-[#f7f6f2]" role="menuitem"><span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-[#ecebff] text-[#635BFF] transition group-hover:bg-[#635BFF] group-hover:text-white"><category.icon size={15} /></span><span><b className="block text-xs font-bold text-[#24234f]">{category.name}</b><small className="mt-0.5 block text-[10px] leading-4 text-[#9b9baa]">{category.description}</small></span></Link>)}
              </div>
            </div>
          </div>
        </nav>
        <div className="hidden flex-1 justify-end gap-3 md:flex">
          <form onSubmit={(e) => { e.preventDefault(); submitSearch() }} className="relative w-[230px]"><Search size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[#9b9baa]" /><input aria-label="Search products" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search products" className="h-10 w-full rounded-full border border-[#e7e6e1] bg-white/75 pl-10 pr-4 text-[13px] outline-none transition focus:border-[#635BFF] focus:ring-4 focus:ring-[#635BFF]/10" /></form>
          <button aria-label="Toggle theme" onClick={toggleTheme} className="flex h-10 w-10 items-center justify-center rounded-full border border-[#e7e6e1] bg-white text-[#6f7184] transition hover:border-[#635BFF]/40 hover:text-[#635BFF]">{theme === 'light' ? <Moon size={16} /> : <Sun size={16} />}</button>
          <Link aria-label={`Wishlist ${wishlistCount} items`} href="/wishlist" className="relative flex h-10 w-10 items-center justify-center rounded-full border border-[#e7e6e1] bg-white text-[#6f7184] transition hover:border-[#635BFF]/40 hover:text-[#635BFF]"><Heart size={16} />{wishlistCount > 0 && <span className="absolute -right-1 -top-1 flex h-5 min-w-5 items-center justify-center rounded-full bg-[#f56f64] px-1 text-[10px] font-bold text-white">{wishlistCount}</span>}</Link>
          <button aria-label={`Shopping bag ${cartCount} items`} onClick={openCart} className="relative flex h-10 w-10 items-center justify-center rounded-full bg-[#24234f] text-white transition hover:bg-[#3b3975]"><ShoppingBag size={16} />{cartCount > 0 && <motion.span key={cartCount} initial={reduced ? false : { scale: 1 }} animate={bump && !reduced ? { scale: [1, 1.3, 1] } : { scale: 1 }} transition={{ duration: reduced ? 0 : 0.25, ease: "easeOut" }} className="absolute -right-1 -top-1 flex h-5 min-w-5 items-center justify-center rounded-full bg-[#f9c74f] px-1 text-[10px] font-bold text-[#24234f]">{cartCount}</motion.span>}</button>
          <Link href="/library" aria-label="Library" className="flex h-10 w-10 items-center justify-center rounded-full border border-[#e7e6e1] bg-white text-[#6f7184] transition hover:border-[#635BFF]/40 hover:text-[#635BFF]"><LibraryBig size={16} /></Link>
        </div>
        <div className="flex items-center gap-2 md:hidden"><button aria-label={`Shopping bag ${cartCount} items`} onClick={openCart} className="relative flex h-9 w-9 items-center justify-center rounded-full bg-[#24234f] text-white"><ShoppingBag size={16} />{cartCount > 0 && <motion.span key={`m-${cartCount}`} initial={reduced ? false : { scale: 1 }} animate={bump && !reduced ? { scale: [1, 1.3, 1] } : { scale: 1 }} transition={{ duration: reduced ? 0 : 0.25 }} className="absolute -right-1 -top-1 flex h-4 min-w-4 items-center justify-center rounded-full bg-[#f9c74f] px-1 text-[9px] font-bold text-[#24234f]">{cartCount}</motion.span>}</button><button aria-label="Open navigation menu" onClick={() => setMenuOpen((v) => !v)} className="flex h-9 w-9 items-center justify-center rounded-full border border-[#e7e6e1] bg-white text-[#24234f]">{menuOpen ? <X size={17} /> : <Menu size={17} />}</button></div>
      </div>
      {menuOpen && <div className="border-t border-[#e7e6e1] bg-white p-4 md:hidden"><div className="mb-3 flex items-center gap-3"><Search size={16} className="text-[#9b9baa]" /><input autoFocus value={search} onChange={(e) => setSearch(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && submitSearch()} placeholder="Search the store" className="h-10 flex-1 border-b border-[#e7e6e1] bg-transparent text-sm outline-none" /></div><div className="space-y-2"><Link onClick={() => setMenuOpen(false)} href="/shop" className="block rounded-xl bg-[#f7f6f2] px-4 py-3 text-sm font-semibold text-[#24234f]">Shop</Link><div className="rounded-xl bg-[#f7f6f2]"><button aria-expanded={mobileCategoriesOpen} onClick={() => setMobileCategoriesOpen((open) => !open)} className="flex w-full items-center justify-between px-4 py-3 text-left text-sm font-semibold text-[#24234f]">Categories <ChevronDown size={16} className={`transition-transform duration-200 ${mobileCategoriesOpen ? 'rotate-180' : ''}`} /></button><div className={`grid overflow-hidden px-2 transition-all duration-200 ${mobileCategoriesOpen ? 'max-h-[420px] pb-2 opacity-100' : 'max-h-0 opacity-0'}`}>{navbarCategories.map((category) => <Link onClick={() => setMenuOpen(false)} key={category.slug} href={`/shop/${category.slug}`} className="flex items-center gap-2 rounded-lg px-2 py-2 text-xs font-semibold text-[#6f7184] hover:bg-white hover:text-[#635BFF]"><category.icon size={14} className="text-[#635BFF]" />{category.name}</Link>)}</div></div><Link onClick={() => setMenuOpen(false)} href="/wishlist" className="block rounded-xl bg-[#f7f6f2] px-4 py-3 text-sm font-semibold text-[#24234f]">Wishlist ({wishlistCount})</Link><Link onClick={() => setMenuOpen(false)} href="/library" className="block rounded-xl bg-[#f7f6f2] px-4 py-3 text-sm font-semibold text-[#24234f]">Library</Link><Link onClick={() => setMenuOpen(false)} href="/cart" className="block rounded-xl bg-[#f7f6f2] px-4 py-3 text-sm font-semibold text-[#24234f]">Cart ({cartCount})</Link><button onClick={toggleTheme} className="w-full rounded-xl bg-[#f7f6f2] px-4 py-3 text-left text-sm font-semibold text-[#24234f]">{theme === 'light' ? 'Dark mode' : 'Light mode'}</button></div></div>}
    </header>
    <CartDrawer />
  </>
}

